'use client';

import * as React from 'react';
import { Input as InputPrimitive } from '@base-ui/react/input';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/lib/utils';

const inputVariants = cva(
  'flex-1 min-w-0 bg-transparent outline-none placeholder:text-muted-foreground file:inline-flex file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground disabled:cursor-not-allowed',
  {
    variants: {
      size: {
        sm: 'h-8 px-2.5 py-1.5 text-sm',
        md: 'h-10 px-3.5 py-2.5 text-sm',
        lg: 'h-12 px-4 py-3 text-base',
      },
    },
    defaultVariants: {
      size: 'md',
    },
  }
);

export interface McInputProps
  extends Omit<React.ComponentProps<'input'>, 'size'>, VariantProps<typeof inputVariants> {
  /** Label rendered above the input. */
  label?: React.ReactNode;
  /** Help text below the input. Replaced by error when present. */
  description?: React.ReactNode;
  /** Truthy = error state. ReactNode = renders the message. `true` = red border only. */
  error?: React.ReactNode;
  /** Inline-start addon (icons, text, dropdowns). */
  addonStart?: React.ReactNode;
  /** Inline-end addon (buttons, badges, spinners). */
  addonEnd?: React.ReactNode;
  /** Block-start addon (toolbar, controls above the input row). */
  addonTop?: React.ReactNode;
  /** Block-end addon (character count, status bar below the input row). */
  addonBottom?: React.ReactNode;
}

function McInput({
  className,
  size = 'md',
  label,
  description,
  error,
  addonStart,
  addonEnd,
  addonTop,
  addonBottom,
  type,
  id,
  disabled,
  required,
  ...props
}: McInputProps) {
  const generatedId = React.useId();
  const inputId = id ?? generatedId;

  const hasError = !!error;
  const errorMessage = typeof error === 'boolean' ? null : error;
  const showError = hasError && !!errorMessage;
  const showDescription = !hasError && !!description;
  const messageId = showError
    ? `${inputId}-error`
    : showDescription
      ? `${inputId}-description`
      : undefined;

  const handleGroupClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const target = e.target as HTMLElement;
    if (!target.closest('button, a, input, select, textarea, [tabindex]')) {
      e.currentTarget.querySelector<HTMLInputElement>('[data-slot="input"]')?.focus();
    }
  };

  return (
    <div data-slot="input-root" className={cn('flex flex-col gap-1.5', className)}>
      {label && (
        <label
          data-slot="input-label"
          htmlFor={inputId}
          className={cn('text-sm font-medium text-foreground', disabled && 'text-muted-foreground')}
        >
          {label}
        </label>
      )}

      <div
        data-slot="input-group"
        data-error={hasError || undefined}
        data-disabled={disabled || undefined}
        role="group"
        onClick={handleGroupClick}
        className={cn(
          // Structure
          'group/input flex min-w-0 cursor-text flex-col rounded-xl border border-border bg-input transition-all',
          // Focus ring — wide soft glow
          'focus-within:border-ring focus-within:ring-4 focus-within:ring-ring/30',
          // Error
          'data-[error]:border-destructive',
          'data-[error]:focus-within:border-destructive data-[error]:focus-within:ring-destructive/20',
          'dark:data-[error]:border-destructive/60 dark:data-[error]:focus-within:ring-destructive/30',
          // Disabled
          'data-[disabled]:pointer-events-none data-[disabled]:opacity-50'
        )}
      >
        {addonTop && (
          <div
            data-slot="input-addon"
            data-align="top"
            className={cn(
              'flex w-full items-center border-b border-border text-muted-foreground select-none',
              "[&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0",
              size === 'sm' && 'gap-1.5 px-2.5 py-1 text-xs',
              size === 'md' && 'gap-2 px-3.5 py-1.5 text-sm',
              size === 'lg' && 'gap-2 px-4 py-2 text-sm'
            )}
          >
            {addonTop}
          </div>
        )}

        <div data-slot="input-row" className="flex items-center">
          {addonStart && (
            <div
              data-slot="input-addon"
              data-align="start"
              className={cn(
                'flex shrink-0 items-center text-muted-foreground select-none',
                "[&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0",
                size === 'sm' && 'gap-1.5 pl-2.5 text-sm',
                size === 'md' && 'gap-2 pl-3.5 text-sm',
                size === 'lg' && 'gap-2 pl-4 text-base'
              )}
            >
              {addonStart}
            </div>
          )}

          <InputPrimitive
            data-slot="input"
            type={type}
            id={inputId}
            disabled={disabled}
            required={required}
            aria-invalid={hasError || undefined}
            aria-describedby={messageId}
            className={cn(inputVariants({ size }), addonStart && 'pl-2', addonEnd && 'pr-2')}
            {...props}
          />

          {addonEnd && (
            <div
              data-slot="input-addon"
              data-align="end"
              className={cn(
                'flex shrink-0 items-center text-muted-foreground select-none',
                "[&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0",
                size === 'sm' && 'gap-1.5 pr-2.5 text-sm',
                size === 'md' && 'gap-2 pr-3.5 text-sm',
                size === 'lg' && 'gap-2 pr-4 text-base'
              )}
            >
              {addonEnd}
            </div>
          )}
        </div>

        {addonBottom && (
          <div
            data-slot="input-addon"
            data-align="bottom"
            className={cn(
              'flex w-full items-center border-t border-border text-muted-foreground select-none',
              "[&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0",
              size === 'sm' && 'gap-1.5 px-2.5 py-1 text-xs',
              size === 'md' && 'gap-2 px-3.5 py-1.5 text-sm',
              size === 'lg' && 'gap-2 px-4 py-2 text-sm'
            )}
          >
            {addonBottom}
          </div>
        )}
      </div>

      {showError && (
        <p
          data-slot="input-error"
          id={`${inputId}-error`}
          role="alert"
          className="text-sm text-destructive"
        >
          {errorMessage}
        </p>
      )}

      {showDescription && (
        <p
          data-slot="input-description"
          id={`${inputId}-description`}
          className="text-sm text-muted-foreground"
        >
          {description}
        </p>
      )}
    </div>
  );
}

export { McInput, inputVariants };
